-- Mesmo lote em um só UPDATE (cabe numa chamada). Guarda: canonicalExpression igual.
update public.challenges c set data = jsonb_set(c.data,'{profNote}',jsonb_build_object('pt',v.pt)) from (values ('expr-a1-001',$q$avoir faim$q$,$q$Em francês a fome se tem, com {avoir}: {j'ai faim}. Nunca {je suis faim}.$q$),('expr-a1-002',$q$avoir soif$q$,$q$Igual à fome: sede se tem. {J'ai soif} serve em qualquer situação, com amigos ou desconhecidos.$q$),('expr-a1-003',$q$avoir raison$q$,$q$Como em português, razão se tem: {avoir raison}. O contrário também vai com {avoir}: {avoir tort}.$q$),('expr-a1m1-001',$q$Enchanté !$q$,$q$Homem escreve {enchanté}, mulher escreve {enchantée}, e o som é o mesmo.$q$),('expr-a1m1-003',$q$Pas mal$q$,$q$Resposta comum a {ça va ?}. Apesar do "nada mal", é positivo: quer dizer "até que bem".$q$),('expr-a1m1-004',$q$Ça marche !$q$,$q$É informal, mas muito comum: com amigos, colegas e até o garçom. Numa situação formal, evite.$q$),('expr-a1m1-005',$q$Pas de problème !$q$,$q$Serve para responder a um {pardon !} ou a um pedido de ajuda, com qualquer pessoa.$q$),('expr-a1m2-001',$q$Bon appétit !$q$,$q$Vale à mesa, antes de comer. Para responder: {merci, vous aussi !} ou {toi aussi !}$q$),('expr-a1m2-002',$q$À table !$q$,$q$É o chamado quando a comida está pronta, bem caseiro: {les enfants, à table !}$q$),('expr-a1m2-003',$q$À tout à l'heure !$q$,$q$Só para quem você vai ver de novo no mesmo dia. Para outro dia, diga {à demain} ou {à bientôt}.$q$),('expr-a1m2-004',$q$Tout de suite$q$,$q$Serve para responder a um chamado: {oui, tout de suite !} Não confunda com {tout à l'heure}.$q$),('expr-a1m2-005',$q$Bonne journée !$q$,$q$É a despedida de dia, com qualquer pessoa: na padaria, no trabalho. À noite, troque por {bonne soirée}.$q$),('expr-a1m3-001',$q$Excusez-moi !$q$,$q$Vem com {vous}: é o jeito educado de abordar quem você não conhece. Com amigos: {excuse-moi}.$q$),('expr-a1m3-002',$q$Je vous en prie$q$,$q$É o {de rien} mais educado, com {vous}. Com amigos: {je t'en prie}. Também cede a vez, como "pode passar".$q$),('expr-a1m3-003',$q$Ça fait combien ?$q$,$q$Na hora de pagar o total, no caixa. Para saber o preço de uma coisa só, pergunte {c'est combien ?}$q$),('expr-a1m3-004',$q$C'est trop cher !$q$,$q$Repare no {trop}: quer dizer "demais". Para só "muito caro", diga {c'est très cher}.$q$),('expr-a1m3-005',$q$Et avec ça ?$q$,$q$É a pergunta do vendedor na feira ou na padaria. Se não quiser mais nada: {c'est tout, merci}.$q$),('expr-a1m4-002',$q$Bon voyage !$q$,$q$Para quem vai viajar, com qualquer pessoa. Antes das férias, também se diz {bonnes vacances !}$q$),('expr-a1m4-003',$q$Bon rétablissement !$q$,$q$Para quem está doente ou se recuperando, com qualquer pessoa. Com amigos, também: {soigne-toi bien !}$q$),('expr-a1m4-004',$q$À tes souhaits !$q$,$q$É com {tu}, para amigos e família. Com quem você não conhece, diga {à vos souhaits !}$q$),('expr-a1m4-005',$q$Quel temps !$q$,$q${Quel temps !} é exclamação, não pergunta. Quase sempre é reclamação, mas o tom pode virar elogio.$q$),('expr-a1m5-001',$q$Fais comme chez toi$q$,$q$Com {tu}, para quem é próximo. Para uma visita mais formal, diga {faites comme chez vous}.$q$),('expr-a1m5-002',$q$Chez moi$q$,$q${Chez} já quer dizer "na casa de": {chez moi}, {chez toi}, {chez Marie}. Não precisa de {maison}.$q$),('expr-a1m5-003',$q$Bienvenue !$q$,$q$Em {bienvenue !} sozinho, a forma não muda para homem ou mulher. Para receber em casa: {bienvenue chez moi}.$q$),('expr-a1m5-004',$q$Ça te va bien !$q$,$q$Para elogiar roupa, cor ou corte de cabelo, com {tu}. Com quem você trata por {vous}: {ça vous va bien}.$q$),('expr-a1m5-005',$q$Ça te plaît ?$q$,$q$Cuidado: quem agrada é a coisa, não a pessoa. Para dizer que gosta, responda {oui, ça me plaît !}$q$),('expr-a1m6-001',$q$Bon week-end !$q$,$q$É a despedida da sexta-feira, no trabalho ou na escola. Em francês se diz {week-end}, com hífen.$q$),('expr-a1m6-002',$q$Bonne soirée !$q$,$q$Serve na despedida; ao chegar, é {bonsoir}. Na hora de dormir, é {bonne nuit}.$q$),('expr-a1m6-003',$q$C'est parti !$q$,$q${C'est parti !} dá a largada com animação: um jogo, uma viagem, uma lição. Serve com qualquer pessoa.$q$),('expr-a1m6-004',$q$Quoi de neuf ?$q$,$q$É informal, para amigos. Depois de um {salut}, cai bem. Sem novidades? Responda {rien de spécial}.$q$),('expr-a1m6-005',$q$Ça fait longtemps !$q$,$q$É o que se diz ao reencontrar alguém depois de muito tempo. Para medir o tempo: {ça fait deux ans}.$q$),('expr-a2-001',$q$coup de main$q$,$q$Bem do dia a dia, serve até com colegas. Quem ajuda {donne un coup de main}: {tu me donnes un coup de main ?}$q$),('expr-a2-002',$q$avoir le trac$q$,$q$É o nervoso de antes: prova, palco, entrevista. Não é medo em geral. Vai com {avoir}: {j'ai le trac}.$q$),('expr-a2-003',$q$faire la grasse matinée$q$,$q$Vai com {faire}: {je fais la grasse matinée}. É o programa clássico do domingo, com qualquer pessoa.$q$),('expr-lote1-001',$q$n'importe quoi$q$,$q$Como "qualquer coisa", é neutro. Como "bobagem", é informal e direto: {tu dis n'importe quoi !} só entre amigos.$q$),('expr-lote1-002',$q$en avoir marre$q$,$q$Não esqueça o {en}: {j'en ai marre}. Para dizer do quê, use {de}: {j'en ai marre du bruit}. É informal.$q$),('expr-lote1-015',$q$passer un coup de fil$q$,$q$Serve com qualquer pessoa, até no trabalho. Para dizer para quem, use {à}: {passer un coup de fil à Paul}.$q$),('expr-lote1-016',$q$faire la queue$q$,$q$Vai com {faire}: {je fais la queue}. Para avisar que tem fila, diga {il y a la queue}.$q$),('expr-lote1-017',$q$avoir hâte$q$,$q$Vai com {de} + verbo: {j'ai hâte de partir}. Só para coisa boa que vai chegar, nunca para pressa.$q$),('expr-lote2-013',$q$nuit blanche$q$,$q$O comum é com {passer}: {j'ai passé une nuit blanche}. Vale para festa, trabalho ou preocupação.$q$),('expr-lote3-006',$q$c'est nul$q$,$q$Informal, para coisas e situações. Com pessoa vira crítica: {il est nul en maths}, péssimo em matemática.$q$),('expr-lote3-007',$q$c'est génial$q$,$q$Vale para qualquer notícia boa: {c'est génial !} E também para pessoas: {il est génial}, "ele é incrível".$q$),('expr-lote3-008',$q$mince alors$q$,$q$É a versão educada de um palavrão: dá para dizer na frente de crianças. Muitas vezes sai só {mince !}$q$),('expr-lote3-012',$q$tomber amoureux$q$,$q$Repare: é {de}, não "por": {tomber amoureux de Julie}. E no passado vai com {être}: {il est tombé}.$q$),('expr-lote4-001',$q$faire semblant$q$,$q$Diferente do nosso "finge que", o normal é {de} + verbo: {il fait semblant de dormir}.$q$),('expr-lote4-002',$q$faire exprès$q$,$q$Muito comum na negativa, para pedir desculpas: {je n'ai pas fait exprès}. O {s} final é mudo.$q$),('expr-001',$q$avoir la gueule de bois$q$,$q$É informal e vai com {avoir}: {j'ai la gueule de bois}. Para o rosto de alguém, {gueule} é grosseira.$q$),('expr-002',$q$casser les pieds$q$,$q$Quem se irrita entra antes do verbo: {tu me casses les pieds}. É informal, mas sem palavrão.$q$),('expr-003',$q$poser un lapin$q$,$q$Quem leva o bolo vem antes do verbo: {il m'a posé un lapin}. Informal, para encontro ou compromisso.$q$),('expr-lote1-003',$q$s'en foutre$q$,$q$Muito comum entre amigos, mas grosseiro: nunca com chefe ou desconhecidos. Neutro: {ça m'est égal}.$q$),('expr-lote1-004',$q$être dans la merde$q$,$q$Vulgar: só com gente muito próxima, e de preferência falando de você mesmo: {je suis dans la merde}.$q$),('expr-lote1-005',$q$ça craint$q$,$q$Muito comum no dia a dia. Também diz que um lugar é perigoso: {ce quartier craint}.$q$),('expr-lote1-006',$q$avoir la flemme$q$,$q$Vai com {de} + verbo: {j'ai la flemme de cuisiner}. Bem informal: com o chefe, melhor não.$q$),('expr-lote1-007',$q$c'est dingue$q$,$q$Serve para surpresa boa ou ruim, igual a {c'est fou}. Informal, para usar com amigos.$q$),('expr-lote1-008',$q$foutre le camp$q$,$q$No imperativo é bem agressivo: {foutez le camp !} Já {je fous le camp} é só "vou embora", mas grosso.$q$),('expr-lote1-009',$q$ta gueule$q$,$q$Ofende de verdade; só entre amigos muito próximos, brincando. Sem grosseria, mas ainda seco: {tais-toi}.$q$),('expr-lote1-010',$q$faire chier$q$,$q$É vulgar: o mais comum é {ça me fait chier}. Com quem você não conhece bem, evite totalmente.$q$),('expr-lote1-011',$q$se prendre la tête$q$,$q$Muito comum no imperativo, para acalmar alguém: {ne te prends pas la tête}. Informal.$q$),('expr-lote1-012',$q$tu parles !$q$,$q$Tudo está no tom irônico: {tu parles !} não pede para a pessoa falar. É informal.$q$),('expr-lote1-013',$q$c'est du gâteau$q$,$q$Repare no {du}, nunca {un}. Na negativa também é comum: {ce n'est pas du gâteau}, "não é moleza".$q$),('expr-lote1-014',$q$avoir le cafard$q$,$q${Cafard} também é barata, mas aqui é só tristeza passageira. Vai com {avoir}: {j'ai le cafard}.$q$),('expr-lote2-001',$q$dégage$q$,$q$É agressivo, coisa de briga. Em outros contextos, o verbo {dégager} quer dizer "liberar".$q$),('expr-lote2-002',$q$se casser$q$,$q$Cuidado: {se casser} também é quebrar, como em {le verre s'est cassé}. O contexto diz se alguém saiu.$q$),('expr-lote2-003',$q$c'est chiant$q$,$q$É vulgar, mas muito ouvido. Dito de alguém, ofende: {il est chiant}. Com desconhecidos, evite.$q$),('expr-lote2-004',$q$avoir la trouille$q$,$q$Igual a {avoir peur}, vai com {avoir} e {de}: {j'ai la trouille de prendre l'avion}. É informal.$q$),('expr-lote2-005',$q$être crevé$q$,$q$É informal e concorda com quem fala: uma mulher diz {je suis crevée}. Num pneu, {crevé} é furado.$q$),('expr-lote2-006',$q$être bourré$q$,$q$Gíria de festa, só com gente próxima. A palavra neutra é {ivre}. Mulher diz {je suis bourrée}.$q$),('expr-lote2-007',$q$avoir la dalle$q$,$q$Gíria, entre amigos ou em casa. Como {avoir faim}, vai com {avoir}: {j'ai la dalle}.$q$),('expr-lote2-008',$q$casser les bonbons$q$,$q$Gíria, só com gente próxima: versão suave de uma expressão grosseira. Repare no {me}: {tu me casses les bonbons}.$q$),('expr-lote2-009',$q$arrête ton char$q$,$q$Informal, entre amigos, para uma história difícil de engolir. Com {vous}: {arrêtez votre char}.$q$),('expr-lote2-010',$q$tomber dans les pommes$q$,$q$Informal e muito comum. No passado, {tomber} vai com {être}: {elle est tombée dans les pommes}.$q$),('expr-lote2-011',$q$donner sa langue au chat$q$,$q$Serve para charadas e adivinhas, entre amigos. O {sa} muda com a pessoa: {je donne ma langue au chat}.$q$),('expr-lote2-012',$q$coûter les yeux de la tête$q$,$q$Quase igual ao português, mas em francês são os olhos {de la tête}. Serve em qualquer conversa.$q$),('expr-lote2-014',$q$jeter l'éponge$q$,$q$Em português se joga a toalha; em francês, a esponja: {jeter l'éponge}. Cabe em qualquer conversa.$q$),('expr-lote2-015',$q$avoir la tête dans les nuages$q$,$q$Em português é o mundo da lua; em francês, as nuvens. Vai com {avoir}: {il a la tête dans les nuages}.$q$),('expr-lote2-016',$q$avoir le cœur sur la main$q$,$q$Elogio que cabe em qualquer conversa. Cuidado com a preposição: o coração fica {sur la main}.$q$),('expr-lote3-001',$q$ça vaut le coup$q$,$q$Muito comum no dia a dia, com qualquer pessoa. Para dizer o contrário: {ça ne vaut pas le coup}.$q$),('expr-lote3-002',$q$pas de bol$q$,$q$Informal, para azar pequeno, como perder o ônibus. Diante de uma notícia triste, {pas de bol} soa leve demais.$q$),('expr-lote3-003',$q$avoir du bol$q$,$q$Repare no {du}: {il a du bol}. Para o azar, diga {pas de bol}. As duas são informais, entre amigos.$q$),('expr-lote3-004',$q$faire gaffe$q$,$q$Informal; num contexto formal, {faites attention}. Cuidado: {faire une gaffe}, com {une}, é cometer uma gafe.$q$),('expr-lote3-005',$q$se planter$q$,$q$Informal. É verbo com {se}, então o passado vai com {être}: {je me suis planté}, ou {plantée} se for mulher.$q$),('expr-lote3-009',$q$mort de rire$q$,$q$Informal. Concorda com quem ri: mulher diz {j'étais morte de rire}. Por escrito, vira {mdr}.$q$),('expr-lote3-010',$q$être au top$q$,$q$Informal, e serve para pessoa, lugar ou coisa: {elle est au top}, {ce restaurant est au top}.$q$),('expr-lote3-011',$q$perdre patience$q$,$q$Repare: em francês não tem artigo, é {perdre patience}, sem {la}. Serve em qualquer conversa.$q$),('expr-lote3-013',$q$ferme-la$q$,$q$Soa grosseiro, mesmo sem palavrão: o {la} é a boca. Mais neutro, mas ainda seco: {tais-toi}.$q$),('expr-lote3-014',$q$fous-moi la paix$q$,$q$Soa irritado e grosseiro, então só com gente muito próxima. Versão educada: {laisse-moi tranquille}.$q$),('expr-lote3-015',$q$tu te fous de moi ?$q$,$q$Gíria para reagir a algo absurdo, só com gente próxima. Mais leve, sem grosseria: {tu te moques de moi ?}$q$),('expr-lote3-016',$q$bordel$q$,$q$Pode chocar, então nada de usar com desconhecidos. Também quer dizer bagunça: {c'est le bordel ici}.$q$),('expr-lote3-017',$q$putain$q$,$q$Serve para raiva, susto e até admiração, mas é grosseiro: reconheça {putain} e evite com desconhecidos.$q$),('expr-lote3-018',$q$espèce de con$q$,$q$Insulto de verdade, que pode gerar briga: melhor só reconhecer. Para mulher, vira {espèce de conne}.$q$),('expr-lote3-019',$q$connard$q$,$q$Insulto forte, melhor só reconhecer. É masculino; para mulher, os franceses dizem {connasse}.$q$),('expr-lote4-003',$q$tourner la page$q$,$q$Mesma imagem do português, e cabe em qualquer conversa, até no trabalho: {il faut tourner la page}.$q$),('expr-lote4-004',$q$en vouloir à quelqu'un$q$,$q$Não tem nada a ver com querer algo. Repare no {en} e no {à}: {je t'en veux}, {elle en veut à son amie}.$q$),('expr-lote4-005',$q$c'est foutu$q$,$q$Informal e um pouco grosseiro: evite no trabalho. Uma versão mais leve é {c'est fichu}.$q$),('expr-lote4-006',$q$être fauché$q$,$q$Informal e bem comum. Concorda com quem fala: uma mulher diz {je suis fauchée}, com o "e" do feminino.$q$),('expr-lote4-007',$q$avoir les boules$q$,$q$Bem informal: fica para os amigos. Repare que vem com {avoir} e o artigo {les}: {j'ai les boules}.$q$),('expr-lote4-008',$q$avoir la pêche$q$,$q$Informal e sempre com {avoir} e {la}: {j'ai la pêche}. Nada a ver com fruta na conversa, é pura energia.$q$),('expr-lote4-009',$q$galérer$q$,$q$Verbo informal, conjugado como {parler}: {j'ai galéré}. Para algo difícil de fazer, diga {c'est la galère}.$q$),('expr-lote4-010',$q$avoir du fric$q$,$q${Le fric} é gíria para {l'argent}: com amigos, tudo bem; numa entrevista ou no banco, fique com {argent}.$q$),('expr-lote4-011',$q$tu m'emmerdes$q$,$q$Vulgar e ofende: entenda quando ouvir, mas evite dizer. Sem palavrão, os franceses dizem {tu m'embêtes}.$q$),('expr-lote4-020',$q$être cinglé$q$,$q$Informal, com amigos. Concorda com a pessoa: {il est cinglé}, {elle est cinglée}.$q$),('expr-b2-001',$q$mettre les points sur les i$q$,$q$Igual ao nosso "pôr os pingos nos is". Em francês também soa firme: {je vais mettre les points sur les i}.$q$),('expr-b2-002',$q$avoir un poil dans la main$q$,$q$Informal e meio brincalhona. Repare no {un}: é sempre {un poil}, um pelo só, nunca {des poils}.$q$),('expr-b2-003',$q$ne pas y aller de main morte$q$,$q$Sempre na negativa, e repare no {y}: {tu n'y vas pas de main morte !}, {il n'y est pas allé de main morte}.$q$),('expr-lote1-018',$q$mon œil !$q$,$q$Informal e irônico. Às vezes os franceses puxam a pálpebra com o dedo ao dizer {mon œil !}$q$),('expr-lote1-019',$q$monter sur ses grands chevaux$q$,$q$O possessivo muda com a pessoa: {je monte sur mes grands chevaux}, {il monte sur ses grands chevaux}.$q$),('expr-lote1-020',$q$avoir un coup de barre$q$,$q$Informal e bem comum depois do almoço. Vem com {avoir} e {un}: {j'ai un coup de barre}.$q$),('expr-lote2-017',$q$avoir un verre dans le nez$q$,$q$Informal e bem-humorada, mais leve que {être bourré}. Serve para falar de alguém, não para ofender.$q$),('expr-lote2-018',$q$coûter la peau des fesses$q$,$q$Versão mais informal de {coûter les yeux de la tête}: {la peau des fesses} é a pele do bumbum. Só entre amigos.$q$),('expr-lote2-019',$q$en faire tout un fromage$q$,$q$Informal. Não esqueça o {en}: {ne va pas en faire tout un fromage !} Em francês o drama vira queijo.$q$),('expr-lote2-020',$q$rire jaune$q$,$q$Igualzinho ao nosso "rir amarelo", e cabe em qualquer conversa. No passado: {il a ri jaune}.$q$),('expr-lote3-020',$q$être à côté de la plaque$q$,$q$Informal, para quem está "viajando" no assunto. Costuma vir com {complètement}: {il est complètement à côté}.$q$),('expr-lote4-012',$q$va te faire voir$q$,$q${Va te faire voir} é grosseira e corta a conversa com raiva. Suaviza um palavrão, mas evite até com amigos.$q$),('expr-lote4-013',$q$tirer la gueule$q$,$q${La gueule} é a boca de bicho, por isso soa grosseira. Entre amigos passa; com o chefe, diga {faire la tête}.$q$),('expr-lote4-014',$q$se foutre de la gueule de quelqu'un$q$,$q$Bem grosseira por causa do {foutre}: só entre amigos. Repare no possessivo: {ils se foutent de notre gueule}.$q$),('expr-lote4-015',$q$être sur les nerfs$q$,$q$Vem com {être} e o artigo {les}: {je suis sur les nerfs}. Informal, mas bem natural no dia a dia.$q$),('expr-lote4-016',$q$il pleut des cordes$q$,$q$Só funciona com {il}, como todo verbo de chuva: {il pleut des cordes}. Nunca diga {ça pleut}.$q$),('expr-lote4-017',$q$mettre le paquet$q$,$q$Informal e positiva: sempre {le paquet}, no singular. No passado: {il a mis le paquet}.$q$),('expr-lote4-018',$q$à fond la caisse$q$,$q$Informal, muito usada para carro e moto. {La caisse} é gíria para carro. Com amigos, só {à fond} já basta.$q$),('expr-lote4-019',$q$ça ne casse pas des briques$q$,$q$Informal e sempre na negativa. Na fala, o {ne} costuma cair: {ça casse pas des briques}.$q$)) v(id,e,pt) where c.id=v.id and c.type='expression' and c.data->>'canonicalExpression'=v.e;
